#!/usr/bin/env node
/**
 * Type generator — dependency-free Node ESM.
 *
 * Reads messages/en.json, flattens it to dot-path keys, and writes
 * messages/keys.d.ts exporting a `MessageKey` union type.
 *
 * Run: npm run i18n:types
 * Commit the generated file. Re-run whenever en.json changes.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const messagesDir = join(__dirname, "..", "messages");

function loadJson(filename) {
  const path = join(messagesDir, filename);
  try {
    return JSON.parse(readFileSync(path, "utf8"));
  } catch (e) {
    console.error(`[i18n:types] Failed to read ${filename}: ${e.message}`);
    process.exit(1);
  }
}

/**
 * Recursively collect all leaf dot-paths from a nested object.
 */
function collectKeys(obj, prefix = "", keys = []) {
  for (const [key, value] of Object.entries(obj)) {
    const path = prefix ? `${prefix}.${key}` : key;
    if (typeof value === "object" && value !== null && !Array.isArray(value)) {
      collectKeys(value, path, keys);
    } else {
      keys.push(path);
    }
  }
  return keys;
}

const en = loadJson("en.json");
const keys = collectKeys(en);

if (keys.length === 0) {
  console.error("[i18n:types] en.json appears to be empty — nothing to generate.");
  process.exit(1);
}

const union = keys.map((k) => `  | ${JSON.stringify(k)}`).join("\n");

const output = `// AUTO-GENERATED by scripts/gen-i18n-types.mjs — do NOT edit manually.
// Re-run \`npm run i18n:types\` after changing messages/en.json.

export type MessageKey =
${union};
`;

const outPath = join(messagesDir, "keys.d.ts");
writeFileSync(outPath, output, "utf8");
console.log(`[i18n:types] Written ${keys.length} keys to messages/keys.d.ts`);
